INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist ein Betriebsrat im Kontext eines Fachinformatikers?', 2, '[{"text": "Arbeitnehmervertretung im Betrieb", "correct": true, "because": "Interessen der Beschäftigten"}, {"text": "Technisches Gremium", "correct": false, "because": "Kein IT-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt ein Betriebsrat?', 3, '[{"text": "Mitbestimmung und Schutz der Arbeitnehmer", "correct": true, "because": "Rechte sichern"}, {"text": "Kostenreduktion", "correct": false, "because": "Indirekt"}, {"text": "Systemoptimierung", "correct": false, "because": "Kein Betriebsrat-Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte hat ein Betriebsrat?', 5, '[{"text": "Informationsrechte", "correct": true, "because": "Einblick in Betriebsdaten"}, {"text": "Mitbestimmungsrechte", "correct": true, "because": "z.B. Arbeitszeiten"}, {"text": "Programmierungsrechte", "correct": false, "because": "Kein IT-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Betriebsrat wird gewählt. b) Er ist nur in großen Firmen Pflicht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Freiwillig ab 5 Mitarbeitern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Betriebsrat als Fachinformatiker?', 4, '[{"text": "Mitbestimmung bei Technikeinsatz", "correct": false, "because": "Relevant für IT"}, {"text": "Informationsrechte", "correct": false, "because": "Wichtig für Arbeit"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Betriebsrat-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Betriebsrat bei der Einführung neuer Software mitbestimmt?', 2, '[{"text": "Ja", "correct": true, "because": "§ 87 BetrVG"}, {"text": "Nein", "correct": false, "because": "Mitbestimmungsrecht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Arbeit eines Betriebsrats?', 3, '[{"text": "Betriebsverfassungsgesetz", "correct": true, "because": "BetrVG ist Grundlage"}, {"text": "Arbeitszeitgesetz", "correct": false, "because": "Anderer Fokus"}, {"text": "Mindestlohngesetz", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zu den Aufgaben eines Betriebsrats?', 5, '[{"text": "Überwachung von Gesetzen", "correct": true, "because": "z.B. Arbeitsschutz"}, {"text": "Förderung der Beschäftigten", "correct": true, "because": "z.B. Weiterbildung"}, {"text": "Softwareentwicklung", "correct": false, "because": "Keine Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Der Betriebsrat hat Mitbestimmung bei Kündigungen. b) Er ist immer Pflicht. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Freiwillig wählbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Betriebsrat unwichtig?', 4, '[{"text": "Informationsrechte", "correct": false, "because": "Grundlage"}, {"text": "Mitbestimmung", "correct": false, "because": "Kernaufgabe"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Betriebsrat Schulungen besuchen?', 2, '[{"text": "Nein", "correct": true, "because": "Freiwillig, aber empfohlen"}, {"text": "Ja", "correct": false, "because": "Kein Zwang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Betriebsrat für IT-Systeme?', 4, '[{"text": "Mitbestimmung bei Technikeinsatz", "correct": true, "because": "z.B. Software"}, {"text": "Datenschutzförderung", "correct": true, "because": "Überwachung"}, {"text": "Hardwareentwicklung", "correct": false, "because": "Keine Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Betriebsrat nur für große Betriebe ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Ab 5 Mitarbeitern möglich"}, {"text": "Ja", "correct": false, "because": "Größenunabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich als Fachinformatiker beim Betriebsrat?', 3, '[{"text": "Mitbestimmung bei IT-Systemen", "correct": true, "because": "Relevanz für Arbeit"}, {"text": "Kostenreduktion", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Betriebsrat hat ein Informationsrecht. b) Er kann selbst Software entwickeln.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist keine Aufgabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein fehlender Betriebsrat?', 5, '[{"text": "Weniger Mitbestimmung", "correct": true, "because": "Kein Einfluss"}, {"text": "Schwächerer Arbeitsschutz", "correct": true, "because": "Keine Kontrolle"}, {"text": "Schnellere Entscheidungen", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker beim Betriebsrat?', 3, '[{"text": "Beratung bei IT-Themen", "correct": true, "because": "Fachwissen"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Betriebsrat digitale Sitzungen abhalten?', 2, '[{"text": "Ja", "correct": true, "because": "Mit Geschäftsordnung"}, {"text": "Nein", "correct": false, "because": "Flexibel erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Betriebsrat für Kommunikation nutzen?', 4, '[{"text": "Microsoft Teams", "correct": true, "because": "Digitale Zusammenarbeit"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
